{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "In healthy volunteers, isradipine—a non-ionizable dihydropyridine—has systemic availability of only 16.5% after oral administration, providing affirmative evidence that a highly lipophilic, non-ionizable molecule of this class can fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Nifedipine, a related dihydropyridine, shows oral bioavailability of about 52-53% in healthy volunteers, which would support F ≥20%; however, its much lower molecular weight and lipophilicity make this high-F outcome poorly transferable to the query's extreme physicochemical profile.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "A pyrazolopyrimidinone analogue achieved 34% oral bioavailability in healthy volunteers, but it contains a basic piperazine-sulfonyl group and is much smaller, so it does not outweigh the low-F expectation for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The most transferable experimental evidence (isradipine) shows F <20% in healthy volunteers, and the query's extreme lipophilicity, high molecular weight, and flexibility would further impair absorption; high-F records come from smaller, more polar molecules and are not transferable. Thus low F is predicted.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No structural similarity details are available to confirm the closest analogue.",
    "No formulation, prodrug, or metabolic stability data are provided for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

